import unittest

from rosterkit.seating import seat_rows
from rosterkit.models import Student


class SeatRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            Student("1", "Halloway", "Juno", "A"),
            Student("2", "Dunmere", "Piet", "A"),
            Student("3", "Varrow", "Ines", "A")
        ]

    def test_sorted_by_last_name_and_split_into_rows(self):
        rows = seat_rows(self.students, 2)
        self.assertEqual(
            rows,
            ["Row 1: Dunmere, Piet | Halloway, Juno", "Row 2: Varrow, Ines"]
        )

    def test_one_row_when_seats_cover_everyone(self):
        rows = seat_rows(self.students, 3)
        self.assertEqual(rows, ["Row 1: Dunmere, Piet | Halloway, Juno | Varrow, Ines"])

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seat_rows(self.students, -2)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seat_rows([], 2)
